import csv, numpy as np
from scipy.optimize import least_squares
h=np.array([.06,.26,.55,.84]); Ts=[100,150,200,300]

def read(tech,T):return np.array([float(r['intensity']) for r in csv.DictReader(open(f'/app/spectra/{tech}_{T}K.csv'))])
def fit(tech,lo,hi,centers,widths):
 x=np.arange(lo,hi+1)
 Y=np.array([read(tech,T)[x-150] for T in Ts])
 # params cL,sL,cH,sH, ampL,ampH, intercept and slope per T
 def calc(p):
  c1,s1,c2,s2,a1,a2,*base=p
  g1=np.exp(-.5*((x-c1)/s1)**2);g2=np.exp(-.5*((x-c2)/s2)**2)
  out=[]
  for i,hi_ in enumerate(h):
   b,s=base[2*i:2*i+2]
   out.append((1-hi_)*a1*g1+hi_*a2*g2+b+s*(x-(lo+hi)/2))
  return np.array(out)
 def res(p):return (calc(p)-Y).ravel()
 p0=[centers[0],widths[0],centers[1],widths[1],max(Y[0]),max(Y[-1]),*sum(([np.median(y[:3]),0] for y in Y),[])]
 fit=least_squares(res,p0,bounds=([lo,1,lo,1,0,0]+[-100,-10]*4,[hi,30,hi,30,1000,1000]+[100,10]*4),max_nfev=20000)
 p=fit.x
 print(tech,'param',np.round(p[:6],2),'rss',np.sum(fit.fun**2),'success',fit.success)
 # calculate implied per band areas at each T, by model amplitudes, gamma exactly
 for c,s,a in [(p[0],p[1],p[4]),(p[2],p[3],p[5])]: print('component',c,s,'area pure',a*s*np.sqrt(2*np.pi),'fractions', h)
 print('peak amps',[(round((1-v)*p[4],2),round(v*p[5],2)) for v in h])
for tech in ['raman_532nm','raman_785nm']:
 fit(tech,220,280,[233,257],[8,9])
PY
